example_design.java:
while (running) {
    try {
        Socket socket = new Socket(HOST, PORT);
        sendReading(socket, buildReading());
        socket.close();
        Thread.sleep(2500);
    } catch (IOException e) {
        waitBeforeRetry();
    } catch (InterruptedException e) {
        running = false;
    }
}

example_stop_pattern.java:
private volatile boolean running = true;

public void shutdown() {
    running = false;
}

public void run() {
    while (running) {
        // reconnect + send + retry loop
    }
}
